def get_components(grid):
    """Get connected components for each color in grid"""
    from collections import deque
    height, width = len(grid), len(grid) if grid else 0

    visited = set()
    components = {}  # color -> list of components, each component is list of (r,c)

    for r in range(height):
        for c in range(width):
            color = grid[r][c]
            if color not in [0, 8] and (r, c) not in visited:  # 0 is empty, 8 is background
                # BFS to find all connected cells of this color
                component = []
                queue = deque([(r, c)])
                local_visited = set([(r, c)])
                while queue:
                    curr_r, curr_c = queue.popleft()
                    component.append((curr_r, curr_c))
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < height and 0 <= nc < width:
                            if grid[nr][nc] == color and (nr, nc) not in local_visited:
                                local_visited.add((nr, nc))
                                queue.append((nr, nc))
                component_set = set(component)
                # Also count adjacent cells of OTHER colors
                for cr, cc in component:
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < height and 0 <= nc < width:
                            other_color = grid[nr][nc]
                            if other_color not in [0, 8]:
                                # This color is adjacent, extend the component
                                if (nr, nc) not in component_set:
                                    component_set.add((nr, nc))
                                    component.append((nr, nc))
                                    visited.add((nr, nc))
                visited.update(component_set)
                components[color] = components.get(color, [])
                if color not in (row := ()) or (row := components[color])[-1] not in component_set:
                    components[color].append(component)

    # Simpler version
    components_per_color = {}
    for color in [1, 2, 3, 4, 5, 6, 7, 9]:  # non-background colors
        components_per_color[color] = []

    for r in range(height):
        for c in range(width):
            color = grid[r][c]
            if color in components_per_color and (r, c) not in visited:
                # BFS
                component = []
                queue = deque([(r, c)])
                local_visited = {(r, c)}
                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < height and 0 <= nc < width:
                            if grid[nr][nc] == color and (nr, nc) not in local_visited:
                                local_visited.add((nr, nc))
                                queue.append((nr, nc))
                components_per_color[color].append(component)

    return components_per_color

