def find_single_cells(grid, color):
    """Find cells of given color where every neighbor is a different color"""
    singles = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                has_same_neighbor = False
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        if grid[nr][nc] == color:
                            has_same_neighbor = True
                            break
                if not has_same_neighbor:
                    singles.append((r, c))
    return singles

