            if grid[r][c] == color and (r, c) not in visited:
                obj = []
                queue = deque([(r, c)])
                local_visited = {(r, c)}
                while queue:
                    cr, cc = queue.popleft()
                    obj.append((cr, cc))
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr, nc) not in local_visited:
                                local_visited.add((nr, nc))
                                queue.append((nr, nc))
                if size_min <= len(obj) <= size_max:
                    objects.append((len(obj), obj))
                visited.update(obj)
    return objects

